resources.string:
uniform mat4 uMVPMatrix;
attribute vec4 vPosition;
attribute vec3 vNormal;
attribute vec2 a_TexCoordinate;
varying vec2 texCoord;

void main() {

    gl_Position = uMVPMatrix * vec4(vPosition.xyz, 1.0);

    texCoord = a_TexCoordinate;
}

precision mediump float;
uniform sampler2D u_Texture;
uniform sampler2D u_TextureTerrain;
uniform sampler2D u_TextureTerrain2;
uniform sampler2D u_TextureTerrain3;
uniform sampler2D shadowTexture;
varying vec2 texCoord;

void main() {

vec4 alpha = texture2D(u_Texture, texCoord);

vec2 texCoordPosition = texCoord - vec2(0.5, 0.5);
texCoordPosition = -texCoordPosition * 20.0;

vec4 color = texture2D(u_TextureTerrain, texCoordPosition);
vec4 color2 = texture2D(u_TextureTerrain2, texCoordPosition);
vec4 color3 = texture2D(u_TextureTerrain3, texCoordPosition);

vec4 finalColor = (color*alpha.r + color2*alpha.g + color3*alpha.b);

finalColor = finalColor * texture2D(shadowTexture, texCoordPosition);

gl_FragColor = finalColor;
}
